<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class CreatorProfile extends Model { protected $fillable=['user_id','public_name','slug','bio','country_code','status','approved_at','reviewed_by']; protected function casts(): array { return ['approved_at'=>'datetime']; } public function user(): BelongsTo { return $this->belongsTo(User::class); } public function media(): HasMany { return $this->hasMany(DigitalMedia::class); } public function verificationCases(): HasMany { return $this->hasMany(CreatorVerificationCase::class); } public function canSell(): bool { return $this->status==='approved' && $this->user?->account_status==='active'; } }